<template><div class="page-heading"><div><span class="eyebrow">WORKSPACE SETTINGS</span><h1>系统管理</h1><p>维护成员与门店，让每份申请找到正确的处理人。</p></div><el-button type="primary" @click="openAccount()"><Icon name="plus" /> 新建账号</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb20" /><section class="panel"><el-tabs v-model="tab"><el-tab-pane label="账号与角色" name="accounts"><el-table :data="accounts" v-loading="loading" empty-text="暂无账号"><el-table-column label="成员" min-width="160"><template #default="{ row }"><div class="cell-title">{{ row.display_name || row.username }}</div><div class="cell-sub">{{ row.username }}</div></template></el-table-column><el-table-column label="业务角色" min-width="140"><template #default="{ row }">{{ roleNames[row.role] || row.role }}</template></el-table-column><el-table-column label="所属门店" min-width="170"><template #default="{ row }">{{ row.store_name || '总部' }}</template></el-table-column><el-table-column label="账号状态" width="115"><template #default="{ row }"><span class="status-pill" :class="row.status === 0 || row.is_active === false ? 'withdrawn' : 'available'"><i></i>{{ row.status === 0 || row.is_active === false ? '已停用' : '启用中' }}</span></template></el-table-column><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" @click="openAccount(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination :current-page="page" :page-size="20" :total="count" layout="total, prev, pager, next" @current-change="value => { page = value; load() }" /></div></el-tab-pane><el-tab-pane label="门店与负责人" name="stores"><div class="tab-actions"><el-button @click="openStore()">新建门店</el-button></div><el-table :data="stores" empty-text="暂无门店"><el-table-column prop="code" label="门店编号" min-width="140" /><el-table-column prop="name" label="门店名称" min-width="180" /><el-table-column label="负责人" min-width="150"><template #default="{ row }">{{ row.manager_name || accounts.find(account => account.id === row.manager_id)?.display_name || accounts.find(account => account.id === row.manager_id)?.username || '未配置' }}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" @click="openStore(row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></section>
  <el-dialog v-model="accountOpen" :title="accountId ? '编辑账号' : '新建账号'" width="520px" :close-on-click-modal="false"><el-form ref="accountRef" :model="accountForm" label-position="top"><el-form-item label="工作账号" prop="username" :rules="[{ required: true, message: '请输入账号' }]"><el-input v-model="accountForm.username" :disabled="!!accountId" maxlength="50" /></el-form-item><el-form-item label="显示名称" prop="display_name" :rules="[{ required: true, message: '请输入姓名或显示名称' }]"><el-input v-model="accountForm.display_name" maxlength="100" /></el-form-item><el-form-item label="邮箱（选填）" prop="email"><el-input v-model="accountForm.email" type="email" placeholder="例如 user@example.com" /></el-form-item><el-form-item label="业务角色"><el-select v-model="accountForm.role" class="full-width"><el-option v-for="(label, value) in roleNames" :key="value" :label="label" :value="value" /></el-select></el-form-item><el-form-item v-if="['employee','manager'].includes(accountForm.role)" label="所属门店" prop="store_id" :rules="[{ required: true, message: '请选择所属门店' }]"><el-select v-model="accountForm.store_id" class="full-width"><el-option v-for="store in stores" :key="store.id" :label="store.name" :value="store.id" /></el-select></el-form-item><el-form-item v-if="!accountId" label="初始密码" prop="password" :rules="[{ required: true, min: 8, message: '请设置至少8位密码' }]"><el-input v-model="accountForm.password" type="password" show-password autocomplete="new-password" /></el-form-item><el-form-item label="账号状态"><el-radio-group v-model="accountForm.status"><el-radio :value="1">启用</el-radio><el-radio :value="0">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="accountOpen = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAccount">保存账号</el-button></template></el-dialog>
  <el-dialog v-model="storeOpen" :title="storeId ? '编辑门店' : '新建门店'" width="480px"><el-form ref="storeRef" :model="storeForm" label-position="top"><el-form-item label="门店编号" prop="code" :rules="[{ required: true, message: '请输入门店编号' }]"><el-input v-model="storeForm.code" /></el-form-item><el-form-item label="门店名称" prop="name" :rules="[{ required: true, message: '请输入门店名称' }]"><el-input v-model="storeForm.name" /></el-form-item><el-form-item label="店长负责人"><el-select v-model="storeForm.manager_id" clearable class="full-width" placeholder="选择该门店店长"><el-option v-for="account in accounts.filter(account => account.role === 'manager')" :key="account.id" :value="account.id" :label="account.display_name || account.username" /></el-select><small class="field-note">先创建门店，再创建店长账号，最后在这里配置负责人。</small></el-form-item></el-form><template #footer><el-button @click="storeOpen = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveStore">保存门店</el-button></template></el-dialog>
</template>
<script setup>
import { ref, reactive, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { get, post, patch, rows, report } from '../api/client'
import { roleNames } from '../utils/format'
import Icon from '../ui/Icon.vue'
const tab = ref('accounts'), accounts = ref([]), stores = ref([]), loading = ref(false), error = ref(''), page = ref(1), count = ref(0), saving = ref(false), accountOpen = ref(false), storeOpen = ref(false), accountId = ref(null), storeId = ref(null), accountRef = ref(), storeRef = ref()
const accountForm = reactive({ username: '', display_name: '', email: '', role: 'employee', store_id: null, status: 1, password: '' }), storeForm = reactive({ code: '', name: '', manager_id: null })
async function load() { loading.value = true; error.value = ''; try { const [data, storeData] = await Promise.all([get('accounts/', { page: page.value }), get('stores/')]); accounts.value = rows(data); count.value = data.count ?? accounts.value.length; stores.value = rows(storeData) } catch (e) { error.value = e.userMessage } finally { loading.value = false } }
function openAccount(account) { accountId.value = account?.id || null; Object.assign(accountForm, { username: account?.username || '', display_name: account?.display_name || account?.username || '', email: account?.email || '', role: account?.role || 'employee', store_id: account?.store_id || null, status: account?.status ?? 1, password: '' }); accountOpen.value = true }
async function saveAccount() { if (saving.value || !await accountRef.value.validate().catch(() => false)) return; saving.value = true; try { const payload = { ...accountForm, store_id: ['employee','manager'].includes(accountForm.role) ? accountForm.store_id : null }; if (accountId.value) delete payload.password; if (!payload.email.trim()) delete payload.email; accountId.value ? await patch(`accounts/${accountId.value}/`, payload) : await post('accounts/', payload); accountOpen.value = false; ElMessage.success('账号已保存。'); await load() } catch (e) { report(e) } finally { saving.value = false } }
function openStore(store) { storeId.value = store?.id || null; Object.assign(storeForm, { code: store?.code || '', name: store?.name || '', manager_id: store?.manager_id || null }); storeOpen.value = true }
async function saveStore() { if (saving.value || !await storeRef.value.validate().catch(() => false)) return; saving.value = true; try { storeId.value ? await patch(`stores/${storeId.value}/`, storeForm) : await post('stores/', storeForm); storeOpen.value = false; ElMessage.success('门店已保存。'); await load() } catch (e) { report(e) } finally { saving.value = false } }
onMounted(load)
</script>
